import{describe,it,expect,beforeEach}from"vitest";import{CulturalQuizEngine}from"../../frontend/js-modules/cultural-quiz-engine.js";describe("CulturalQuizEngine",()=>{let e;beforeEach(()=>{e=new CulturalQuizEngine}),it("should initialize with zero score and streak",()=>{expect(e.score).toBe(0),expect(e.streak).toBe(0)}),it("should calculate points with multiplier on streaks",()=>{e.submitAnswer(!0,10),expect(e.score).toBe(10),expect(e.streak).toBe(1),e.submitAnswer(!0,10),e.submitAnswer(!0,10),expect(e.streak).toBe(3),expect(e.score).toBe(35)}),it("should reset streak on incorrect answer",()=>{e.submitAnswer(!0,10);const t=e.submitAnswer(!1,10);expect(t.streak).toBe(0),expect(e.streak).toBe(0)}),it("should unlock badges when meeting eligibility thresholds",()=>{e.score=55;const t=e.checkBadgeEligibility();expect(t.length).toBe(1),expect(t[0].name).toBe("Heritage Explorer")}),it("should serialize state accurately",()=>{e.score=100,e.streak=5;const t=e.serializeState();expect(t).toContain('"score":100'),expect(t).toContain('"streak":5')})});